import{_ as o,o as a,c as t,a0 as i}from"./chunks/framework.DB31oXgM.js";const p=JSON.parse('{"title":"ADR-009: ML Models as Advisory-Only (No Auto-Action)","description":"","frontmatter":{},"headers":[],"relativePath":"ADR_009_ml_advisory_only.md","filePath":"ADR_009_ml_advisory_only.md"}'),n={name:"ADR_009_ml_advisory_only.md"};function r(s,e,l,d,c,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-009-ml-models-as-advisory-only-no-auto-action" tabindex="-1">ADR-009: ML Models as Advisory-Only (No Auto-Action) <a class="header-anchor" href="#adr-009-ml-models-as-advisory-only-no-auto-action" aria-label="Permalink to &quot;ADR-009: ML Models as Advisory-Only (No Auto-Action)&quot;">​</a></h1><p><strong>Date:</strong> 2026-10-11<br><strong>Status:</strong> ACCEPTED<br><strong>Context:</strong> F4, D5 — ML pipeline and anti-cheat<br><strong>Decision:</strong> ML predictions inform admins but never trigger automatic bans, kicks, or score resets</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>ML models (anomaly detection, jitter prediction, rollback risk) can flag suspicious patterns. But ML is probabilistic:</p><ol><li>False positives: Legitimate spike in latency flagged as &quot;degradation&quot;</li><li>False negatives: Real cheater not detected</li><li>Model drift: Training data from Month 1 doesn&#39;t apply to Month 6</li></ol><p>Using ML to auto-ban players is dangerous and player-hostile.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Three-tier system:</p><ol><li><strong>Passive monitoring:</strong> ML models compute scores (confidence 0–100) but never trigger actions</li><li><strong>Admin review:</strong> Scores above threshold (e.g., 75) appear in admin dashboard as &quot;Review Incident&quot;</li><li><strong>Explicit action:</strong> Admin clicks &quot;Confirm Ban&quot; → audit log recorded → player banned (not auto)</li></ol><p><strong>Models in scope:</strong></p><ul><li>Anomaly detection (input/state/network patterns): flags unusual behavior</li><li>Jitter predictor: predicts latency degradation; used to adjust adaptive delay</li><li>Rollback risk: estimates session churn risk; used to prioritize matchmaking</li><li>Capacity forecaster: predicts server load; triggers autoscaling alerts (not auto-scale)</li></ul><p><strong>No auto-actions:</strong></p><ul><li>No automatic bans</li><li>No automatic score adjustments</li><li>No automatic disconnects</li><li>No automatic incident creation (ML creates &quot;alerts&quot;, humans create &quot;incidents&quot;)</li></ul><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><ul><li><strong>Player trust:</strong> Players accept suspension if admins explain it; they reject unexplained auto-bans</li><li><strong>Legal/compliance:</strong> Auto-bans without human review expose to legal challenge</li><li><strong>Model improvement:</strong> Admins provide feedback (false positive/negative) to retrain models</li><li><strong>Gradual rollout:</strong> Start advisory; if model proven stable over 6 months, consider auto-action (Phase 3 ⏳)</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Requires admin interface (<code>/admin/incidents</code>) with dashboard and review workflow</li><li>Model retraining loop: feedback from admins → retrain quarterly</li><li>Latency impact: Low (scores computed async, not on hot path)</li></ul><h2 id="implemented-in-code" tabindex="-1">Implemented In Code <a class="header-anchor" href="#implemented-in-code" aria-label="Permalink to &quot;Implemented In Code&quot;">​</a></h2><p><strong>⏳</strong> ML models: <code>backend/src/aiml/models/*.py</code> — pending F4</p><p><strong>⏳</strong> Advisory wrapper: <code>backend/src/admin/mod.rs::create_incident_from_ml()</code> — pending D5</p><p><strong>⏳</strong> Admin review: <code>backend/src/admin/mod.rs::review_incident()</code> — pending F2</p><p><strong>⏳</strong> Audit trail: <code>schema.sql</code> — <code>incidents</code> table with state = (pending, approved, dismissed)</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>F4: ML pipeline (data, models, safety)</li><li>D5: Anti-cheat (audit trail, no auto-ban)</li><li>F2: Admin APIs</li><li>Phase 3: Consider auto-action after 6 months of stable operation</li></ul>',24)])])}const g=o(n,[["render",r]]);export{p as __pageData,g as default};
